mapper.select:
SELECT kind,identity,stamp FROM (
  SELECT 'CONTENT' kind,CAST(q.id AS CHAR) identity,SHA2(CAST(JSON_ARRAY(q.title,q.stem_html,q.answer_html,q.analysis_html,q.stem_hash,q.subject,q.question_type,q.content_kind,q.difficulty,q.creation_kind,q.source_note,q.layout_mode,q.unit_kind,q.pagination_mode,q.layout_note,q.item_count,q.has_image) AS CHAR),256) stamp FROM kb_question q WHERE q.id=#{questionId}
  UNION
  SELECT 'KP' kind,CAST(k.id AS CHAR) identity,CAST(JSON_ARRAY(k.row_version,k.subject) AS CHAR) stamp
  FROM kb_question_kp qk JOIN kb_kp k ON k.id=qk.kp_id WHERE qk.question_id=#{questionId}
  UNION
  SELECT 'OUTLINE',CAST(o.id AS CHAR),CAST(JSON_ARRAY(o.row_version,o.status,o.subject,o.catalog_kind) AS CHAR)
  FROM kb_question_kp qk JOIN kb_kp_outline ko ON ko.kp_id=qk.kp_id JOIN kb_outline o ON o.id=ko.outline_id WHERE qk.question_id=#{questionId}
  UNION
  SELECT 'NODE',CONCAT(nk.kp_id,':',n.id),CAST(JSON_ARRAY(n.row_version,n.outline_id) AS CHAR)
  FROM kb_question_kp qk JOIN kb_outline_node_kp nk ON nk.kp_id=qk.kp_id JOIN kb_outline_node n ON n.id=nk.node_id WHERE qk.question_id=#{questionId}
  UNION
  SELECT 'SOURCE',CAST(s.id AS CHAR),CAST(JSON_ARRAY(s.row_version,s.source_kind) AS CHAR)
  FROM kb_question_source qs JOIN kb_source s ON s.id=qs.source_id WHERE qs.question_id=#{questionId}
  UNION
  SELECT 'OCCURRENCE',CAST(qs.id AS CHAR),CAST(JSON_ARRAY(qs.row_version,qs.source_id,qs.match_status,qs.matched_stem_hash) AS CHAR)
  FROM kb_question_source qs WHERE qs.question_id=#{questionId}
  UNION
  SELECT 'ASSET',CAST(a.asset_id AS CHAR),CAST(JSON_ARRAY(a.status,a.sha256,a.file_size) AS CHAR)
  FROM kb_question_asset qa JOIN kb_asset a ON a.asset_id=qa.asset_id WHERE qa.question_id=#{questionId}
  UNION
  SELECT 'SOURCE_ASSET',CONCAT(sa.source_id,':',a.asset_id),CAST(JSON_ARRAY(a.status,a.sha256,a.file_size,sa.role) AS CHAR)
  FROM kb_question_source qs JOIN kb_source_asset sa ON sa.source_id=qs.source_id JOIN kb_asset a ON a.asset_id=sa.asset_id WHERE qs.question_id=#{questionId}
  UNION
  SELECT 'EVIDENCE_ASSET',CAST(a.asset_id AS CHAR),CAST(JSON_ARRAY(a.status,a.sha256,a.file_size) AS CHAR) FROM kb_question_source qs JOIN kb_asset a ON a.asset_id=qs.evidence_asset_id WHERE qs.question_id=#{questionId}
  UNION
  SELECT 'PARENT',CAST(p.id AS CHAR),SHA2(CAST(JSON_ARRAY(p.title,p.stem_html,p.answer_html,p.analysis_html,p.subject,p.question_type,p.content_kind,p.creation_kind,p.source_note,p.layout_mode,p.unit_kind,p.pagination_mode,p.layout_note,d.is_primary,d.operation,d.change_note,d.preserved_note) AS CHAR),256)
  FROM kb_question_derivation d JOIN kb_question p ON p.id=d.parent_question_id WHERE d.child_question_id=#{questionId}
) f ORDER BY kind,identity,stamp

WITH RECURSIVE impacted(id) AS ( SELECT q.id FROM kb_question q WHERE
q.id=#{id} EXISTS(SELECT 1 FROM kb_question_source qs WHERE qs.question_id=q.id AND qs.source_id=#{id}) EXISTS(SELECT 1 FROM kb_question_source qs WHERE qs.question_id=q.id AND qs.id=#{id}) EXISTS(SELECT 1 FROM kb_question_kp qk WHERE qk.question_id=q.id AND qk.kp_id=#{id}) EXISTS(SELECT 1 FROM kb_question_kp qk JOIN kb_outline_node_kp nk ON nk.kp_id=qk.kp_id WHERE qk.question_id=q.id AND nk.node_id=#{id}) EXISTS(SELECT 1 FROM kb_question_kp qk JOIN kb_kp_outline ko ON ko.kp_id=qk.kp_id WHERE qk.question_id=q.id AND ko.outline_id=#{id}) 1=0
UNION DISTINCT SELECT d.child_question_id FROM kb_question_derivation d JOIN impacted i ON i.id=d.parent_question_id ) SELECT id FROM impacted ORDER BY id LIMIT #{limit}

SELECT kb_question.id FROM kb_question WHERE kb_question.id IN
#{id}
AND  ORDER BY kb_question.id
